        var malformedEffect=NifMaterial.Read(effectShader,null,Array.Empty<string>());Check(malformedEffect.effect!.colorScale==null&&malformedEffect.effect.softDepth==null&&malformedEffect.effect.invalidFields.Length==2&&System.Text.Json.JsonSerializer.Serialize(malformedEffect).Contains("\"colorScale\":null"),"Invalid effect numbers remain unavailable and cannot break the bounded JSON response");
        effectShader.Type=NiflySharp.Helpers.ShaderHelper.ShaderGameType.FO4;Check(NifMaterial.Read(effectShader,null,Array.Empty<string>()).effect==null,"Non-Skyrim effect versions are not interpreted with Skyrim field semantics");
        var rotation=new NiflySharp.Structs.Matrix33{M11=0,M12=-1,M21=1,M22=0,M33=1};var normal=NifGeometry.Normal(new System.Numerics.Vector3(4,0,0),rotation,3);Check(System.Numerics.Vector3.Distance(normal,new System.Numerics.Vector3(0,1,0))<0.00001,"Authored normals rotate and normalize without translation or scale length");
        bool badNormal=false;try{NifGeometry.Normal(System.Numerics.Vector3.Zero,rotation,1);}catch(InvalidDataException){badNormal=true;}Check(badNormal,"Zero authored normals are rejected for geometric fallback");
        Check(NifGeometry.Normal(new System.Numerics.Vector3(1,0,0),rotation,-2).Y==-1,"Mirrored scale transforms the authored normal direction");
        var reflected=new NiflySharp.Structs.Matrix33{M11=-1,M22=1,M33=1};var face=new[]{0,1,2};NifGeometry.OrientTriangles(face,NifGeometry.Handedness(reflected,1));
        var facePoints=new[]{System.Numerics.Vector3.Zero,System.Numerics.Vector3.UnitX,System.Numerics.Vector3.UnitY}.Select(v=>NifGeometry.Transform(v,reflected,1,System.Numerics.Vector3.Zero)).ToArray();
        var faceNormal=System.Numerics.Vector3.Normalize(System.Numerics.Vector3.Cross(facePoints[face[1]]-facePoints[face[0]],facePoints[face[2]]-facePoints[face[0]]));
        Check(System.Numerics.Vector3.Dot(faceNormal,NifGeometry.Normal(System.Numerics.Vector3.UnitZ,reflected,1))>.999f,"Mirrored triangle front face agrees with its transformed authored normal");
        face=new[]{0,1,2};NifGeometry.OrientTriangles(face,NifGeometry.Handedness(reflected,1)*NifGeometry.Handedness(rotation,-1));Check(face.SequenceEqual(new[]{0,1,2}),"Two reflected parent transforms preserve original triangle winding");
        var shear=new NiflySharp.Structs.Matrix33{M11=1,M12=2,M22=1,M33=1};var tangent=NifGeometry.Transform(System.Numerics.Vector3.UnitY,shear,1,System.Numerics.Vector3.Zero);var shearedNormal=NifGeometry.Normal(System.Numerics.Vector3.UnitX,shear,1);Check(Math.Abs(System.Numerics.Vector3.Dot(tangent,shearedNormal))<.00001f,"Inverse-transpose keeps normals perpendicular under non-orthogonal imported matrices");
        bool singular=false;try{NifGeometry.Handedness(new NiflySharp.Structs.Matrix33{M11=1,M22=1,M33=0},1);}catch(InvalidDataException){singular=true;}Check(singular,"Singular geometry transforms fail before producing a collapsed preview");
        bool badTransform=false;try{NifGeometry.Handedness(new NiflySharp.Structs.Matrix33{M11=1,M22=1,M33=1,M12=float.NaN},1);}catch(InvalidDataException){badTransform=true;}Check(badTransform,"Nonfinite off-diagonal transform entries are rejected");
        face=new[]{0,1,2,2,1,3};NifGeometry.OrientTriangles(face,-1);Check(face.SequenceEqual(new[]{0,2,1,2,3,1}),"Every reflected triangle changes winding without changing vertex identity");
        var inverse=NifGeometry.Inverse(rotation,2,new System.Numerics.Vector3(8,-3,7));var original=new System.Numerics.Vector3(3,4,9);var skinPoint=NifGeometry.Transform(original,rotation,2,new System.Numerics.Vector3(8,-3,7));var restored=NifGeometry.Transform(skinPoint,inverse.rotation,inverse.scale,inverse.translation);Check(System.Numerics.Vector3.Distance(original,restored)<.0001f,"Global-to-skin inverse restores translated rotated scaled bind coordinates");
        inverse=NifGeometry.Inverse(shear,-2,new System.Numerics.Vector3(-4,2,8));skinPoint=NifGeometry.Transform(original,shear,-2,new System.Numerics.Vector3(-4,2,8));restored=NifGeometry.Transform(skinPoint,inverse.rotation,inverse.scale,inverse.translation);Check(System.Numerics.Vector3.Distance(original,restored)<.0001f,"Bind inverse handles shear and negative scale without losing translation");
        bool invalidBind=false;try{NifGeometry.Inverse(rotation,1,new System.Numerics.Vector3(float.NaN,0,0));}catch(InvalidDataException){invalidBind=true;}Check(invalidBind,"Nonfinite skin translation is rejected");
        addonRecord.WeightSliderEnabled.Male=true;var weightedAddon=RecordData.Read(addonRecord)!;
        var armorRoot=new RecordData{Key="000400:Test.esm",Type="Armor",Fields=new(){{"Armature",new[]{new{FormKey=weightedAddon.Key}}}}};
        var variants=ModelVariants.Resolve(armorRoot,key=>key==weightedAddon.Key?weightedAddon:throw new Exception("Unexpected linked record"));
        Check(variants.Count==2&&variants.All(v=>v.sex=="Male"&&v.pose=="Worn reference pose"),"Armor resolves linked worn models even when it has no dropped model; missing sex is not substituted");
        Check(variants.Any(v=>v.weight==0&&v.derivedWeightPath&&v.path.EndsWith("male_0.nif"))&&variants.Any(v=>v.weight==100&&!v.derivedWeightPath&&v.path.EndsWith("male_1.nif")),"Enabled weight endpoint produces a separately identified candidate requiring actual asset resolution");
        Check(variants.All(v=>v.record==weightedAddon.Key&&v.priority=="2"),"Model variant keeps exact addon identity and sex-specific priority");
        addonRecord.WeightSliderEnabled.Male=false;var fixedAddon=RecordData.Read(addonRecord)!;var fixedVariants=ModelVariants.Resolve(fixedAddon,_=>throw new Exception("No linked read expected"));Check(fixedVariants.Count==1&&fixedVariants[0].weight==null&&!fixedVariants[0].derivedWeightPath,"Weight endpoints are not invented when the addon disables the slider");
        bool unrelated=false;try{ModelVariants.Select(variants,"different-record|Male");}catch(InvalidDataException){unrelated=true;}Check(unrelated,"Arbitrary variant identity cannot select an unrelated asset");
        var deletedArmor=new RecordData{Key="000401:Test.esm",Type="Armor",Deleted=true};bool deletedModel=false;try{ModelVariants.Resolve(deletedArmor,_=>weightedAddon);}catch(InvalidDataException){deletedModel=true;}Check(deletedModel,"Deleted armor cannot supply a preview variant");
        bool wrongAddon=false;try{ModelVariants.Resolve(armorRoot,_=>new RecordData{Type="Weapon"});}catch(InvalidDataException){wrongAddon=true;}Check(wrongAddon,"Armature link must resolve to an actual armor addon");
        var unsafeModel=new RecordData{Key="000402:Test.esm",Type="Weapon",Assets=new(){@"..\outside.nif"}};bool unsafeVariant=false;try{ModelVariants.Resolve(unsafeModel,_=>weightedAddon);}catch(InvalidDataException){unsafeVariant=true;}Check(unsafeVariant,"Model variant paths remain inside the existing asset resolver boundary");
        var staticWeapon=new RecordData{Key="000403:Test.esm",Type="Weapon",Assets=new(){@"Weapons\sword.nif"}};var weaponVariant=ModelVariants.Resolve(staticWeapon,_=>throw new Exception("No addon expected")).Single();Check(weaponVariant.pose=="Static"&&weaponVariant.sex==""&&weaponVariant.path==@"meshes\Weapons\sword.nif","Existing static weapon preview remains a direct asset choice");
        ModelTextureOverrideChecks.Run(Check);
        TravelDoorChecks.Run(Check);
        Console.WriteLine(JsonSerializer.Serialize(new{ok=true,checks}));
    }
