    static (int width,int height,byte[] pixels) ReadPreviewPng(byte[] png){
        if(!png.Take(8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))throw new Exception("Expected PNG signature");
        int width=0,height=0;using var compressed=new MemoryStream();
        for(int offset=8;offset<png.Length;){int size=System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(offset,4));string type=System.Text.Encoding.ASCII.GetString(png,offset+4,4);if(type=="IHDR"){width=System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(offset+8,4));height=System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(png.AsSpan(offset+12,4));if(png[offset+16]!=8||png[offset+17]!=6)throw new Exception("Expected RGBA8 PNG");}if(type=="IDAT")compressed.Write(png,offset+8,size);offset+=12+size;}
        compressed.Position=0;using var zip=new System.IO.Compression.ZLibStream(compressed,System.IO.Compression.CompressionMode.Decompress);using var pixels=new MemoryStream();zip.CopyTo(pixels);return(width,height,pixels.ToArray());
    }
